style.css:
/* Сброс стилей и базовые настройки */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Общие настройки */
body {
  font-family: Arial, sans-serif;
  background-color: #121212; /* Тёмный фон */
  color: #e0e0e0; /* Светлый текст */
  transition: background-color 0.3s, color 0.3s;
}

/* Стили для ссылок */
a {
  color: #bb86fc; /* Светло-фиолетовый для ссылок */
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Стили для заголовков */
h1, h2, h3, h4, h5, h6 {
  color: #ffffff; /* Белые заголовки */
}

/* Медиазапрос для переключения на тёмную тему */
@media (prefers-color-scheme: dark) {
  body {
    background-color: #121212; /* Тёмный фон */
    color: #e0e0e0; /* Светлый текст */
  }
  
  /* Стили для кнопок */
  button {
    background-color: #333333;
    color: #ffffff;
    border: 1px solid #444444;
  }

  button:hover {
    background-color: #555555;
  }
  
  /* Стили для форм и input */
  input, textarea {
    background-color: #333333;
    color: #e0e0e0;
    border: 1px solid #444444;
  }

  input:focus, textarea:focus {
    border-color: #bb86fc; /* Подсветка при фокусе */
  }
}

/* Стили для светлой темы (по умолчанию) */
@media (prefers-color-scheme: light) {
  body {
    background-color: #ffffff; /* Светлый фон */
    color: #121212; /* Тёмный текст */
  }

  /* Стили для кнопок */
  button {
    background-color: #f1f1f1;
    color: #121212;
    border: 1px solid #cccccc;
  }

  button:hover {
    background-color: #e0e0e0;
  }
  
  /* Стили для форм и input */
  input, textarea {
    background-color: #f1f1f1;
    color: #121212;
    border: 1px solid #cccccc;
  }

  input:focus, textarea:focus {
    border-color: #6200ee; /* Подсветка при фокусе */
  }
}
